# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İMANIN MAHİYETİ: TASDİK, İKRAR VE TEVHİD-ŞEHADET</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">İMANIN UNSURLARI (KALP VE DİL)</text>\n  <rect x="42" y="78" width="280" height="65" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="52" y="98" font-size="12" font-weight="bold" fill="#1d4ed8">1. Kalp ile Tasdik (Asli ve Zorunlu Unsur):</text>\n  <text x="52" y="116" font-size="11" fill="#1e3a8a">Hz. Peygamber\'in Allah\'tan getirdiği kesin olarak</text>\n  <text x="52" y="132" font-size="11" fill="#1e3a8a">bilinen esasları (zarûrât-ı dîniyye) kalben onaylamak.</text>\n  <rect x="42" y="152" width="280" height="75" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="52" y="172" font-size="12" font-weight="bold" fill="#1d4ed8">2. Dil ile İkrar (Dünyevi Hükümler İçin):</text>\n  <text x="52" y="190" font-size="11" fill="#1e3a8a">Kalpteki inancı dil ile söyleyerek açıklamaktır.</text>\n  <text x="52" y="206" font-size="10.5" fill="#3b82f6">• Münafık: Kalben inanmadığı hâlde dille inandığını söyleyen.</text>\n  <text x="52" y="220" font-size="10.5" fill="#3b82f6">• Mümin: Kalbiyle tasdik edip diliyle ikrar eden kimse.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KELİME-İ TEVHİD VE KELİME-İ ŞEHADET</text>\n  <rect x="372" y="78" width="286" height="70" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="515" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Kelime-i Tevhid: لَا إِلٰهَ إِلَّا اللّٰهُ مُحَمَّدٌ رَسُولُ اللّٰهِ</text>\n  <text x="515" y="115" text-anchor="middle" font-size="11" fill="#14532d">(Lâ ilâhe illallah Muhammedün Resûlullah)</text>\n  <text x="515" y="133" text-anchor="middle" font-size="10.5" fill="#166534">"Allah\'tan başka ilah yoktur, Muhammed O\'nun elçisidir."</text>\n  <rect x="372" y="156" width="286" height="72" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="515" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Kelime-i Şehadet: أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ ...</text>\n  <text x="515" y="192" text-anchor="middle" font-size="10.5" fill="#14532d">"Ben şahitlik ederim ki Allah\'tan başka ilah yoktur ve yine</text>\n  <text x="515" y="208" text-anchor="middle" font-size="10.5" fill="#14532d">şahitlik ederim ki Muhammed O\'nun kulu ve elçisidir."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KAPSAMINA GÖRE İMAN: İCMALÎ İMAN VE TAFSİLÎ İMAN</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">İCMALÎ İMAN (TOPTAN / ÖZET İMAN)</text>\n  <text x="40" y="94" font-size="11.5" fill="#78350f">• İnanılacak esaslara ayrıntılarına girmeden,</text>\n  <text x="48" y="112" font-size="11.5" font-weight="bold" fill="#92400e">bütüncül ve özet olarak inanmaktır.</text>\n  <text x="40" y="138" font-size="11.5" fill="#78350f">• Kelime-i Tevhid ve Kelime-i Şehadet cümleleriyle</text>\n  <text x="48" y="156" font-size="11.5" fill="#78350f">ifade edilir; imanın ilk ve temel basamağıdır.</text>\n  <rect x="42" y="174" width="280" height="52" rx="6" fill="#ffedd5" stroke="#f59e0b"/>\n  <text x="182" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Âmentü\'deki İcmalî İfade:</text>\n  <text x="182" y="212" text-anchor="middle" font-size="11" fill="#7c2d12">"Allah\'a ve Hz. Muhammed\'in getirdiklerinin tamamına inandım."</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">TAFSİLÎ İMAN (AYRINTILI İMAN - 6 ESAS)</text>\n  <text x="370" y="92" font-size="11.5" fill="#581c87">• İnanç esaslarının her birine ayrı ayrı ve</text>\n  <text x="378" y="110" font-size="11.5" font-weight="bold" fill="#6b21a8">ayrıntılı biçimde (Âmentü esaslarıyla) inanmaktır:</text>\n  <text x="375" y="134" font-size="11.5" fill="#581c87">1. Allah\'a iman          4. Peygamberlere iman</text>\n  <text x="375" y="156" font-size="11.5" fill="#581c87">2. Meleklere iman        5. Ahiret gününe iman</text>\n  <text x="375" y="178" font-size="11.5" fill="#581c87">3. İlahi kitaplara iman  6. Kader ve kazaya iman</text>\n  <rect x="372" y="192" width="286" height="36" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="515" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">İман esasları bir bütündür; birini inkâr etmek hepsini inkârdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DELİLE DAYANMASI BAKIMINDAN İMAN: TAKLİDÎ VE TAHKİKÎ İMAN</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="182" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">TAKLİDÎ İMAN</text>\n  <text x="40" y="94" font-size="11.5" fill="#881337">• Delillere ve araştırmaya dayanmadan, kişinin</text>\n  <text x="48" y="112" font-size="11.5" font-weight="bold" fill="#9f1239">ailesinden ve çevresinden gördüğü şekilde</text>\n  <text x="48" y="130" font-size="11.5" fill="#881337">benimsediği imandır.</text>\n  <text x="40" y="156" font-size="11.5" fill="#881337">• İslam âlimlerine göre taklidî iman geçerlidir</text>\n  <text x="48" y="174" font-size="11.5" fill="#881337">(sahibi mümindir); ancak şüphe ve itirazlar</text>\n  <text x="48" y="192" font-size="11.5" fill="#881337">karşısında sarsılma tehlikesi taşır.</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Kişi imanını delillerle güçlendirmekle sorumludur.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="515" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">TAHKİKÎ İMAN (BİLİNÇLİ VE DELİLLİ İMAN)</text>\n  <text x="370" y="94" font-size="11.5" fill="#164e63">• Akli ve naklî delillere, bilgiye, araştırmaya,</text>\n  <text x="378" y="112" font-size="11.5" font-weight="bold" fill="#0e7490">tefekküre ve kalbî kavrayışa dayanan imandır.</text>\n  <text x="370" y="138" font-size="11.5" fill="#164e63">• Kâinattaki düzeni gözlemleyerek, Kur\'an\'ı ve</text>\n  <text x="378" y="156" font-size="11.5" fill="#164e63">sünneti anlayarak ulaşılan bilinçli inançtır.</text>\n  <rect x="372" y="174" width="286" height="52" rx="6" fill="#cffafe" stroke="#06b6d4"/>\n  <text x="515" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#155e75">İman - Bilgi - Salih Amel İlişkisi:</text>\n  <text x="515" y="212" text-anchor="middle" font-size="11" fill="#164e63">Sahih bilgi tahkikî imanı, tahkikî iman ise salih ameli besler.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
